class ResultType {
public:
    ResultType() = default;
    ResultType(const ResultType&) = delete; // Proof of elision
    // If RVO fails, compilation error results.
};

// Named Return Value Optimization (NRVO) example
ResultType factory_nrvo() {
    ResultType local_obj; // Named object
    return local_obj;     // NRVO attempts to construct caller's
                          // object at 'local_obj' location.
}

ResultType r = factory_nrvo();
// The object 'r' is constructed once.


// Guaranteed Copy Elision (C++17 Prvalue)
ResultType factory_prvalue() {
    // Returning an unnamed temporary (prvalue)
    return ResultType(); // Elision is guaranteed here (mandatory)
}

ResultType s = factory_prvalue();
// The object 's' is constructed once.
